using namespace std;
using namespace ResourceDASM;

// ---- Mac Toolbox trap-number -> name (the subset we care about; extended live) ----
// ADBBTRACE: module-range basic-block PC tracer, armed only during the draw call, to diff
// two runs (e.g. Modern Art Mondrian vs Pollock) and find the gate branch where they diverge.
// ADTVSTRIDE: bytes per TV/JT island. Host default 8 ({4EF9,target.l,0000}); the '+ODE' engine appears to
// index a 6-byte table ({4EF9,target.l}) — the recurring tvBase+6 fault is entry 1 of a 6-byte stride.
static uint32_t g_tvStride(){ static uint32_t v = getenv("ADTVSTRIDE") ? (uint32_t)strtoul(getenv("ADTVSTRIDE"),0,0) : 8; return v; }
static uint32_t g_jtBias(){ static uint32_t v = getenv("ADJTBIAS") ? (uint32_t)strtoul(getenv("ADJTBIAS"),0,0) : 0; return v; }
// Set once the authentic near-model jump-table layout has been built (the CodeWarrior runtime
// block at its absolute A5+0x20 base plus a disjoint base per fragment).
static bool g_jtAuth=false;
// Near-JT slots the HOST owns (e.g. the __mul32 MULU.L helper at A5+0x42). The dll# DRLT self-reloc
// path writes {4EF9,method} islands into the low near-JT band and would otherwise
// CLOBBER these, silently redirecting a runtime-helper call to an unrelated C++ method.
static std::set<uint32_t> g_reservedJT;
// ==== sfBand live/dead near-JT slot classifier (execution-based) ====
// A near-JT slot is LIVE iff module code can actually REACH a read/jump-through of it at runtime.
// Static scans (ADSFNEARSCAN: pea/lea (d16,A5) sites) over-approximate — DEAD code has address-take
// sites too, so a static scan evicts bands that could harmlessly overlap dead slots. The dataflow
// answer is EXECUTION: run the module (init + frames) and record which module-world (A5==a5_mod)
// near-JT slots are ACTUALLY jumped-through / address-taken. That executed set is the LIVE set.
// ADSFLIVEPROBE turns on the recorder; the atexit dump ([sflive]) prints it + a band-overlap validator.
static bool     g_sfLiveProbe=false;   // ADSFLIVEPROBE: record executed near-JT slot accesses
static uint32_t g_sf_a5mod=0;          // module-world A5 base, published from the loader for the probe
static uint32_t g_sf_tvbase=0;         // module-world TV band base (upper bound of the near-JT island band)
static std::set<int32_t> g_sfJumped;   // signed a5_mod-relative offsets JUMPED-through (jsr/jmp (d16,A5))
static std::set<int32_t> g_sfAddrTaken;// signed a5_mod-relative offsets ADDRESS-TAKEN (pea/lea (d16,A5))
static std::vector<std::pair<int32_t,int32_t>> g_sfBands;  // allocated de-alias band ranges (a5_mod-relative)
static void sf_live_dump(){
  static bool done=false; if(done) return; done=true;
  if(!g_sfLiveProbe) return;
  auto pr=[&](const char* tag, std::set<int32_t>& s){
    fprintf(stderr,"[sflive] %s live near-JT slots (a5_mod-relative), n=%zu:",tag,s.size());
    for(int32_t o : s) fprintf(stderr," %+d",o);
    fprintf(stderr,"\n"); };
  pr("JUMPED", g_sfJumped);
  pr("ADDR-TAKEN", g_sfAddrTaken);
  // near-JT completion: dump the EXECUTED near-JT island-address-take d16 set to a file (ADSFISLOUT) so a
  // second run's NEARSCAN can restrict itself to LIVE raw pea/lea sites (raw ∩ executed = genuine islands).
  // Only positive above-a5 island slots below tvBase with (d16&7)==2 matter for islandTop.
  if(getenv("ADSFISLOUT")){ FILE* f=fopen(getenv("ADSFISLOUT"),"w");
    if(f){ uint32_t tvoff=g_sf_tvbase-g_sf_a5mod;
      for(int32_t o : g_sfAddrTaken) if(o>0 && (o&7)==2 && (uint32_t)o<tvoff) fprintf(f,"%d\n",o);
      for(int32_t o : g_sfJumped)    if(o>0 && (o&7)==2 && (uint32_t)o<tvoff) fprintf(f,"%d\n",o);
      fclose(f); } }
  // VALIDATOR: a de-alias band overlapping a JUMPED-through near-JT ISLAND slot would clobber a live jump
  // island (the real clobber class). Address-takes INSIDE a band are the band's own de-alias targets (the
  // module reading its relocated far-globals via rewritten (d16,A5) refs) — NOT a clobber. Clean = 0 jumped.
  int jclob=0;
  for(auto& b : g_sfBands){
    for(int32_t o : g_sfJumped) if(o>=b.first && o<b.second){
      fprintf(stderr,"[sflive] *** CLOBBER: band [%+d,%+d) overlaps LIVE JUMPED slot %+d ***\n",b.first,b.second,o); jclob++; }
    int atk=(int)std::count_if(g_sfAddrTaken.begin(),g_sfAddrTaken.end(),[&](int32_t o){return o>=b.first&&o<b.second;});
    fprintf(stderr,"[sflive] band [%+d,%+d): jumped-overlaps=%d addr-take-targets=%d (addr-takes are de-alias targets, expected)\n",
      b.first,b.second, (int)std::count_if(g_sfJumped.begin(),g_sfJumped.end(),[&](int32_t o){return o>=b.first&&o<b.second;}), atk);
  }
  fprintf(stderr,"[sflive] VERDICT: %s (%d live-jumped-slot band clobbers)\n", jclob==0?"SAFE — no band clobbers a live jump island":"UNSAFE", jclob);
}
// ==== ADJTLIVE: execution-based census of the LOW A5 near-JT band ====
// The static question "is a baked `pea/lea/jsr (d16,A5)` with 0 < d16 < 0x3800 a jump-table slot or a
// plain A5-relative global?" cannot be settled by a linear-sweep disassembly (misdecodes manufacture
// both forms). Execution settles it: record every (d16,A5) control transfer / address take that the
// emulator ACTUALLY executes in the shared library A5 world, with the caller PC (so library code and
// module code are distinguishable) and what the slot held at the time.
struct JtlRec { long jmp=0, addr=0; uint32_t pcJmp=0, pcAddr=0, pcJmpMax=0, pcAddrMax=0; };
// ADJTXPROBE: record which near-JT ISLANDS actually execute, by their jump TARGET. Island
// addresses move when the layout is corrected, so comparing addresses across builds is meaningless —
// comparing the set of methods reached is not. Any method that appears on one side only is a dispatch
// whose binding the de-aliasing changed.
static bool g_jtx=false; static uint32_t g_jtx_lo=0, g_jtx_hi=0;
static std::map<std::pair<uint32_t,uint32_t>,long> g_jtxTarget;   // (island addr, jump target) -> count
static void jtx_dump(){
  static bool done=false; if(done) return; done=true;
  if(!g_jtx) return;
  fprintf(stderr,"[jtx] executed near-JT islands: %zu distinct targets\n",g_jtxTarget.size());
  for(auto& kv : g_jtxTarget) fprintf(stderr,"[jtx]  island %08X -> %08X  x%ld\n",kv.first.first,kv.first.second,kv.second);
}
static bool     g_jtlive=false;
// Executed-PC ring shared by the ADPCTRACE dump and the ADWATCHRING dump.
static const uint32_t G_PCRINGSZ=4096;
static uint32_t g_pcring[G_PCRINGSZ]; static uint32_t g_pcringN=0;
// ADRD2HIST executed-PC histogram (16-byte buckets over one address range, dumped at exit).
// With ADRD2MAP (loader-side name->address dump) this makes "which functions execute zero
// times" a two-command census on any dll# module.
// CAVEAT: hook-based PC counts are LOWER BOUNDS — a zero bucket needs a second evidence axis.
static std::vector<unsigned long long> g_rd2_hist;
static uint32_t g_rd2_hlo=0;
static void rd2_hist_dump(){
  unsigned long long tot=0; size_t hot=0;
  for(auto v : g_rd2_hist){ tot+=v; if(v) hot++; }
  fprintf(stderr,"[rd2hist] lo=%08X buckets=%zu executed=%zu total_instr=%llu\n",g_rd2_hlo,g_rd2_hist.size(),hot,tot);
  if(getenv("ADRD2HISTRAW")){
    for(size_t k=0;k<g_rd2_hist.size();k++) if(g_rd2_hist[k])
      fprintf(stderr,"[rd2raw] %08X %llu\n",(unsigned)(g_rd2_hlo+(k<<4)),g_rd2_hist[k]);
  }
  // Runs of consecutive executed buckets = the code regions that ran at all.
  size_t i=0;
  while(i<g_rd2_hist.size()){
    if(!g_rd2_hist[i]){ i++; continue; }
    size_t j=i; unsigned long long su=0;
    while(j<g_rd2_hist.size() && g_rd2_hist[j]){ su+=g_rd2_hist[j]; j++; }
    fprintf(stderr,"[rd2hist] RUN %08X..%08X (%zu B) instr=%llu\n",
      (unsigned)(g_rd2_hlo+(i<<4)),(unsigned)(g_rd2_hlo+(j<<4)),(size_t)((j-i)<<4),su);
    i=j; }
}
static uint32_t g_jtl_a5=0;
static std::map<int32_t,JtlRec> g_jtlBySlot;
static void jtl_dump(){
  static bool done=false; if(done) return; done=true;
  if(!g_jtlive) return;
  fprintf(stderr,"[jtlive] A5=%08X  distinct executed (d16,A5) slots in (0,0x3800): %zu\n",g_jtl_a5,g_jtlBySlot.size());
  for(auto& kv : g_jtlBySlot){
    const JtlRec& r=kv.second;
    fprintf(stderr,"[jtlive]  A5+0x%04X  jumped=%-6ld (pc %08X..%08X)  addrTaken=%-6ld (pc %08X..%08X)\n",
      (unsigned)kv.first,r.jmp,r.pcJmp,r.pcJmpMax,r.addr,r.pcAddr,r.pcAddrMax);
  }
}
// ==== ADSFFP: per-module near-A5 WRITE-FOOTPRINT recorder ====
// Captures a module's INTRINSIC near-A5 (s16 window) write footprint across its WHOLE run (init +
// self-animation). RD self-animates under the plain single-run drive, so the animation-phase
// footprint the sfBand allocator must avoid is reachable without a queued input drive.
// Mechanism: baseline the s16 window at the FIRST module instruction (post-load, pre-init), then diff it
// once per presented frame and OR any changed byte into an ever-touched map. The de-alias BAND span is
// EXCLUDED at dump time (a module writing its own relocated far-globals is legitimate, NOT a region the
// band must avoid — this is exactly the ADSFDATASCAN ambiguity, resolved by execution: band cells are
// where WE put the globals, everything else touched is the module's own near-A5 data). ADSFFPOUT writes
// the a5_mod-relative touched ranges to a file; the allocator reads them back via ADSFFPIN (2-pass probe).
static bool     g_sffp=false;
static uint32_t g_sffp_a5=0, g_sffp_lo=0, g_sffp_hi=0;      // window [a5_mod+WINLO, a5_mod+WINHI) absolute
static std::vector<uint8_t> g_sffp_base, g_sffp_touch;      // load-time baseline + ever-differed map
static uint32_t g_sffp_bandlo=0, g_sffp_bandhi=0;           // union of placed de-alias band spans (absolute)
static long     g_sffp_snaps=0;
static void sffp_dump(){
  static bool done=false; if(done) return; done=true;      // idempotent: atexit + signal handler
  if(!g_sffp || g_sffp_base.empty()) return;
  // Exclude the placed band cells: writes there are the module's own relocated far-globals, not "avoid".
  if(g_sffp_bandhi>g_sffp_bandlo)
    for(uint32_t a=g_sffp_bandlo;a<g_sffp_bandhi;a++) if(a>=g_sffp_lo&&a<g_sffp_hi) g_sffp_touch[a-g_sffp_lo]=0;
  FILE* out=nullptr; const char* op=getenv("ADSFFPOUT"); if(op) out=fopen(op,"w");
  fprintf(stderr,"[sffp] window [a5_mod%+d,a5_mod%+d) snaps=%ld band=[a5_mod%+d,a5_mod%+d)\n",
    (int)(g_sffp_lo-g_sffp_a5),(int)(g_sffp_hi-g_sffp_a5),g_sffp_snaps,
    (int)((int32_t)(g_sffp_bandlo-g_sffp_a5)),(int)((int32_t)(g_sffp_bandhi-g_sffp_a5)));
  if(out) fprintf(out,"a5_mod %08X\nband %d %d\n",g_sffp_a5,
    (int)((int32_t)(g_sffp_bandlo-g_sffp_a5)),(int)((int32_t)(g_sffp_bandhi-g_sffp_a5)));
  long nb=0,nr=0; uint32_t rlo=0; bool inrun=false;
  for(uint32_t i=0;i<=g_sffp_touch.size();i++){
    bool t = (i<g_sffp_touch.size()) && g_sffp_touch[i];
    if(t && !inrun){ rlo=g_sffp_lo+i; inrun=true; }
    else if(!t && inrun){ uint32_t rhi=g_sffp_lo+i;
      int rl=(int)(int32_t)(rlo-g_sffp_a5), rh=(int)(int32_t)(rhi-g_sffp_a5);
      fprintf(stderr,"[sffp] TOUCH a5_mod%+d..a5_mod%+d len=%d\n",rl,rh,rh-rl);
      if(out) fprintf(out,"touch %d %d\n",rl,rh);
      nr++; nb+=(rh-rl); inrun=false; }
  }
  fprintf(stderr,"[sffp] DONE nbytes=%ld nruns=%ld (band-excluded)\n",nb,nr);
  if(out){ fprintf(out,"done %ld %ld\n",nb,nr); fclose(out); }
}
// ==== ADSFRD: above-a5 READ / JUMP / address-reg probe ====
// A write-diff cannot see a READ or a JUMP-through of the above-a5 window, so this probe records,
// per a5_mod-relative slot in a window, every instruction that (R) reads a source EA in the window,
// (X) executes with PC in the window, or (A) holds an address register pointing into the window —
// tagged by A5 world. Runs on every instruction, including the animation phase. ADSFRDLO/HI bound
// the window (a5_mod-relative hex, default 0x40..0x3800).
static bool     g_sfrd=false, g_sfrd_ea=false;
static uint32_t g_sfrd_a5=0, g_sfrd_lo=0, g_sfrd_hi=0, g_sfrd_a5lib=0;
static long     g_sfrd_steps=0;
struct SfRdRec{ long r=0,x=0,areg=0; uint32_t exPc=0,rdPc=0,aPc=0; long libW=0,modW=0,othW=0; };
static std::map<int32_t,SfRdRec> g_sfrdBySlot;   // a5_mod-relative slot -> accesses
static void sfrd_dump(){
  static bool done=false; if(done)return; done=true;
  if(!g_sfrd) return;
  fprintf(stderr,"[sfrd] window [a5_mod%+d,a5_mod%+d) steps=%ld distinctSlots=%zu (R=read X=exec A=aregPtr)\n",
    (int)(int32_t)(g_sfrd_lo-g_sfrd_a5),(int)(int32_t)(g_sfrd_hi-g_sfrd_a5),g_sfrd_steps,g_sfrdBySlot.size());
  std::vector<std::pair<int32_t,SfRdRec>> v(g_sfrdBySlot.begin(),g_sfrdBySlot.end());
  std::sort(v.begin(),v.end(),[](auto&a,auto&b){return (a.second.r+a.second.x+a.second.areg)>(b.second.r+b.second.x+b.second.areg);});
  int shown=0; for(auto&pr:v){ if(shown++>=50)break; auto&r=pr.second;
    fprintf(stderr,"[sfrd]  slot a5_mod%+d  R=%ld(pc%08X) X=%ld(pc%08X) A=%ld(pc%08X) world{lib=%ld mod=%ld oth=%ld}\n",
      pr.first,r.r,r.rdPc,r.x,r.exPc,r.areg,r.aPc,r.libW,r.modW,r.othW); }
}
// ==== ADSFXPROBE: EXECUTED-IN-GAP island probe ====
// A near-JT slot in the clean above-a5 gap [islandTop_base, tvBase) is a GENUINE live island iff the module
// EXECUTES CODE there (PC lands in it). RD executes a contiguous island run at a5_mod+[0x46A,0x51E]
// (+0x1E2E,+0x37FE); Art Critic and Bad Dog! execute nothing in the gap (their above-a5 near-A5 use
// is pure de-alias-band DATA, never code). "Band must not overlap a slot the module executes"
// therefore separates RD (band must stay OUT of the gap) from AC/Bad Dog! (bands stay in the gap)
// with no module names. Cheap: one PC range-test per instruction. Dump -> ADSFXOUT for the
// allocator's 2-pass islandTop. Placement-robust: RD jumps into its island region even when a band
// clobbers it, so the probe may run in any fixed placement.
static bool     g_sfx=false;
static uint32_t g_sfx_a5=0, g_sfx_lo=0, g_sfx_hi=0;
static std::set<int32_t> g_sfxSlots;      // a5_mod-relative slots where module-world PC executed
// ==== [pf] DUTY CENSUS (measurement only; ADPFDUTY=1) ====
// Counts how often each per-instruction hook duty actually FIRES, so the zero-hook design is driven by
// measured fire rates rather than by assumption. Zero production cost: every increment sits behind a
// const bool captured at install time.
enum PfDuty { PFD_INSTR=0, PFD_SFX, PFD_SBCAP, PFD_BUGSEXT, PFD_BUGSDEPTH,
              PFD_SBREADER, PFD_DLLBUDGET, PFD_DDWALK, PFD_RETSENT, PFD_TMFIRE, PFD_TICK,
              PFD_NULLRTS, PFD_KEYPC, PFD_KEYFED, PFD_N };
static uint64_t g_duty[PFD_N];
static const char* g_duty_name[PFD_N] = {"instructions","sfx_island","sb_capture","bugs_ext","bugs_getdepth",
  "sb_reader","dll_budget","dd_walkfix","ret_sentinel","tm_fire","tick_spin",
  "null_rts","keypump_pc","keypump_fed"};
static void pf_duty_dump(){ if(!getenv("ADPFDUTY")) return;
  for(int i=0;i<PFD_N;i++) fprintf(stderr,"[duty] %-16s %llu\n", g_duty_name[i],(unsigned long long)g_duty[i]); }

// ==== [pf] EMULATOR OPCODE-CAPABILITY CHECK ====
// The M68K opcode defects this probe checks for are fixed in the emulator itself (PRs #97 merged and
// #100 open; until #100 lands, the local third_party clone carries the patches named in the error
// text below), so the host carries no per-instruction shims for them.
//
// The probe is a DIAGNOSTIC: it executes each opcode once on a throwaway emulator, and if the library
// we are linked against gets any of them wrong it prints ONE warning naming the defect and its
// remedy -- and then RUNS ANYWAY. It does not gate the run. The defects here are not crashes, they
// are wrong condition codes and wrong arithmetic that come out the far end as a plausible-looking
// but wrong render -- which is exactly what the warning is there to name, so that such a render is
// never mistaken for the module's real output.
// Cost is startup-only: five one-instruction runs, once, before any module code executes.
static std::function<void()> g_pf_install_hook;   // [pf] installs the lean hook on demand (dynamic arming)
static bool g_pf_hook_installed=false;            // is a hook currently attached?
static bool g_pf_zero_hook=false;                 // this run started with NO hook at all
static const uint16_t PF_SENT_TRAP=0xAFFE;        // host-owned A-line sentinel written at RET_SENT
// [pf] Servicing the sentinel as a TRAP costs one on_cycle_start. Ticks are scheduled off that same
// cycle count, so without correction the sentinel mechanism would silently shift every module's tick
// PHASE. Record the debt and hand it back to the next tick interval, so how the sentinel is detected
// does not change when ticks land.
static uint64_t g_pf_cycle_debt=0;
// [pf] Same mechanism for the dll# null-method shim. A null service slot makes `jsr [A0]` land at pc<0x10,
// which is host-allocated, host-zeroed scratch that nothing else in the host reads or writes — so an A-line
// trap there is host-owned, not a guest-code patch.
static const uint16_t PF_NULLRTS_TRAP=0xAFFD;
static void pf_probe_emulator_opcodes(){
  const uint32_t B=0x00200000;
  auto step=[&](std::function<void(M68KEmulator&)> setup, const uint16_t* words, size_t n,
                std::function<bool(M68KEmulator&)> check)->bool{
    try{
      auto m=std::make_shared<MemoryContext>();
      m->allocate_at(B,0x200);
      for(size_t i=0;i<n;i++) m->write_u16b(B+(uint32_t)i*2, words[i]);
      M68KEmulator e(m);
      auto& r=e.registers(); r.pc=B; r.a[7]=B+0x180;
      setup(e);
      int steps=0;
      e.set_debug_hook([&steps](M68KEmulator&){ if(steps++>=1) throw EmulatorBase::terminate_emulation(); });
      try{ e.execute(); }catch(const EmulatorBase::terminate_emulation&){}
      return check(e);
    }catch(...){ return false; }
  };
  // 1) EXTB.L D0 — sign-extend byte to long. Unreachable in an unpatched build (its `case 7` sits under
  //    `if (g == 0)` but EXTB.L has bit 8 set), so the opcode decodes as lea/chk and D0 is left wrong.
  const uint16_t w1[]={0x49C0};
  bool ok1=step([](M68KEmulator& e){ e.registers().d[0].u=0x123456FF; }, w1,1,
                [](M68KEmulator& e){ return e.registers().d[0].u==0xFFFFFFFFu; });
  // 2) bfextu D0{0:8},D1 with a REGISTER source — an unpatched build throws "unimplemented bfextu from register".
  const uint16_t w2[]={0xE9C0,0x1008};
  bool ok2=step([](M68KEmulator& e){ e.registers().d[0].u=0xFF000000; e.registers().d[1].u=0; }, w2,2,
                [](M68KEmulator& e){ return e.registers().d[1].u==0xFFu; });
  // 3) subx.l D1,D0 with D0=0, D1=0x80000000, X=0 -> 0 - (-2^31) overflows, so V MUST be set. An unpatched
  //    build computes the check in int32_t, which wraps and hides exactly this case.
  const uint16_t w3[]={0x9181};
  bool ok3=step([](M68KEmulator& e){ auto&r=e.registers(); r.d[0].u=0; r.d[1].u=0x80000000u; r.sr.u=0; }, w3,1,
                [](M68KEmulator& e){ auto&r=e.registers(); return r.d[0].u==0x80000000u && (r.sr.u&0x02)!=0; });
  // 4) swap.w D0 with D0=0x000000FE and Z ALREADY SET (as `clr.w D0` leaves it). SWAP sets N and Z from the
  //    32-bit result and clears V and C; a build that only exchanges the halves leaves the stale Z, so the
  //    `beq` that every CodeWarrior 32-bit divide helper puts right after its `clr.w/swap.w` pair branches
  //    the wrong way. Probed separately from the other three because those are already fixed upstream and
  //    this one is not, so an upstream fix can retire this arm alone.
  const uint16_t w4[]={0x4840};
  bool ok4=step([](M68KEmulator& e){ auto&r=e.registers(); r.d[0].u=0x000000FE; r.sr.u=0x04 /*Z*/; }, w4,1,
                [](M68KEmulator& e){ auto&r=e.registers(); return r.d[0].u==0x00FE0000u && (r.sr.u&0x04)==0; });
  // 5) cmpa.w A0,#0 with A0=0x000A0000 -- a 64K-ALIGNED but plainly NON-NULL address. Z must come back
  //    CLEAR. resource_dasm passes size=SIZE_WORD to set_ccr_flags_integer_subtract (M68KEmulator.cc:2601),
  //    which sign_extends the 32-bit An down to its low word, so every 64K-aligned address compares EQUAL
  //    to zero. That turns LIB510's `operator new` null-check (`cmpa.w A0,#0 / bne` at 0x0100442C) into a
  //    false "allocation failed" -> Throw(0x101) -> the module builds nothing. Probed separately from the
  //    other four for the same reason ok4 is: so an upstream fix can retire this arm alone.
  const uint16_t w5[]={0xB0FC,0x0000};
  bool ok5=step([](M68KEmulator& e){ auto&r=e.registers(); r.a[0]=0x000A0000; r.sr.u=0; }, w5,2,
                [](M68KEmulator& e){ return (e.registers().sr.u&0x04)==0; });
  const bool all_ok = ok1 && ok2 && ok3 && ok4 && ok5;
  if(getenv("ADLEANLOG"))
    fprintf(stderr,"[pf] emulator opcode probe: EXTB.L=%s bitfield-reg=%s ADDX/SUBX-V=%s SWAP-ccr=%s CMPA.W-width=%s -> %s\n",
            ok1?"ok":"MISSING", ok2?"ok":"MISSING", ok3?"ok":"MISSING", ok4?"ok":"MISSING", ok5?"ok":"MISSING",
            all_ok?"emulator is complete (no host shims exist)":"INCOMPLETE (warned; running anyway)");
  if(all_ok) return;
  // Name every missing fix and the remedy for it. This is the whole diagnosis: whoever hits this is almost
  // always someone who re-cloned third_party and lost the local patches.
  fprintf(stderr,
    "\n*** adhost68k: the resource_dasm this host is linked against is MISSING M68K emulator fixes. ***\n"
    "This host carries NO emulator-defect shims -- every defect is fixed in the emulator itself -- so\n"
    "affected modules will render as the deficient emulator computes them. Continuing anyway;\n"
    "the list below explains any wrong-looking render.\n\n");
  struct { bool ok; const char* defect; const char* remedy; } arms[] = {
    {ok1, "EXTB.L decodes as lea/chk (sign-extend byte->long never happens)",
          "resource_dasm master past PR #97 (merged)"},
    {ok2, "register-direct bitfield ops throw 'unimplemented bfextu from register'",
          "resource_dasm master past PR #97 (merged)"},
    {ok3, "ADDX/SUBX overflow computed in int32_t, so V is wrong at INT_MIN",
          "resource_dasm master past PR #97 (merged)"},
    {ok4, "SWAP does not set the condition codes (N/Z stale from the previous instruction)",
          "PR #100, or apply tools/adhost/scratchpad/swap_upstream.diff"},
    {ok5, "CMPA.W compares at WORD width, so 64K-aligned addresses test equal to zero",
          "PR #100, or apply tools/adhost/scratchpad/cmpa_upstream.diff"},
  };
  for(const auto& a : arms) if(!a.ok) fprintf(stderr, "  MISSING: %s\n           remedy: %s\n", a.defect, a.remedy);
  fprintf(stderr,
    "\nUpdate third_party/resource_dasm past PRs #97 (merged) and #100, or check out the PR branch, or\n"
    "apply the local patches listed in tools/adhost/README.md, then rebuild libresource_file.a and relink.\n\n");
}
