  for(auto& e : g_sgp_ctlen)   fprintf(stderr,"[sgp]   clut_scan_len=%u x%llu\n",e.first,e.second);
  fprintf(stderr,"[sgp] distinct_input_streams=%zu over %llu passes\n",g_sgp_streams.size(),g_sgp_ci);
