        g_banner_text=s; g_banner_x=C.pen_h; g_banner_y=C.pen_v; g_banner_fg=C.qd_fg; g_banner_have=true;
        if(getenv("ADBANNERLOG")) fprintf(stderr,"[banner] captured pc=%08X x=%d y=%d fg=%d \"%s\"\n",r.pc,g_banner_x,g_banner_y,g_banner_fg,s.c_str());
