      if(erp){ mem->write_u16b(erp,upd?6:0); mem->write_u32b(erp+2, upd?mem->read_u32b(0x9DE):0);  // what; message=WindowList head
               mem->write_u32b(erp+6,nowt); mem->write_u32b(erp+10,0); mem->write_u16b(erp+14,0); }
