      // ADFRAGCALL: log transitions INTO the AD3-Code fragment block [0x02000000,0x02010A28) — i.e. which
      // Canvas/fragment methods the module actually calls. Builds the live JT map for the dll# draw-commit RE.
      if(CENV("ADFRAGCALL") && g_bbtrace_on){ static uint32_t fprev=0; static int fn=0;
        bool infrag = (rr.pc>=0x02000000 && rr.pc<0x02011000);
        bool wasfrag = (fprev>=0x02000000 && fprev<0x02011000);
        if(infrag && !wasfrag && fn++<80) fprintf(stderr,"    [fragcall] from=%08X -> frag=%08X D0=%08X D1=%08X A0=%08X\n",fprev,rr.pc,rr.d[0].u,rr.d[1].u,rr.a[0]);
        fprev=rr.pc; }
