            auto nzr=[&](uint32_t a,uint32_t n)->long{ long c=0; for(uint32_t i=0;i<n;i+=4){ uint32_t v=0; try{v=mem->read_u32b(a+i);}catch(...){} if(v)c++; } return c; };
