            int f10=0,f14=0,f1c=0,fc=0,f72=0; try{f10=(int)mem->read_u32b(obj+0x10);f14=(int)mem->read_u32b(obj+0x14);f1c=(int)mem->read_u32b(obj+0x1C);fc=(int)mem->read_u32b(obj+0xC);f72=(int)mem->read_u32b(obj+0x72);}catch(...){}
