            int side=0,f8=0,fc=0,f10=0; try{f8=(int)mem->read_u32b(obj+0x8);fc=(int)mem->read_u32b(obj+0xC);f10=(int)mem->read_u32b(obj+0x10);}catch(...){} side=f8;
