            uint32_t cnt=std::min<uint32_t>(pcringN,40);
            fprintf(stderr,"        ring:"); for(uint32_t i=0;i<cnt;i++){ uint32_t idx=(pcringN-cnt+i)&(PCRINGSZ-1); fprintf(stderr," %08X",pcring[idx]); }
            fprintf(stderr,"\n");
